<?php
// --- Configuração Inicial e Segurança ---
require 'db_connect.php';

// Verificar se a conexão foi estabelecida corretamente
if (!$conn || $conn->connect_error) {
    die("Erro crítico na conexão com o banco de dados. Tente novamente mais tarde.");
}

// Variáveis globais para armazenar resultados intermediários (para o HTML)
$escolas = null;
$professores = null;
$turmas = null; // Será usada tanto para populosel como para exibição final
$turma_info = [];

// --- Funções Auxiliares ---

/**
 * Cria a cláusula IN segura para um array de valores
 */
function buildWhereClause($column, $values, &$types, &$params): string {
    if (empty($values)) {
        return '';
    }

    // Remove 'all' caso esteja presente para evitar busca gigantesca
    $cleanValues = array_filter($values, function($val) {
        return $val !== 'all';
    });

    if (empty($cleanValues)) {
        return '';
    }

    $placeholders = implode(',', array_fill(0, count($cleanValues), '?'));
    $types .= str_repeat('s', count($cleanValues));

    foreach ($cleanValues as $value) {
        $params[] = $value;
    }

    return "$column IN ($placeholders)";
}

/**
 * Determina quais turmas buscar baseado nos filtros passados
 * Retorna o resultado do query ou null
 */
function getFilteredTurmas($conn, $filters): ?mysqli_result {
    $gre = isset($filters['gre']) && !empty(array_filter($filters['gre'])) ? $filters['gre'] : [];
    $escola = isset($filters['escola']) && !empty(array_filter($filters['escola'])) ? $filters['escola'] : [];
    $professor = isset($filters['professor']) && !empty(array_filter($filters['professor'])) ? $filters['professor'] : [];
    $turma = isset($filters['turma']) && !empty(array_filter($filters['turma'])) ? $filters['turma'] : [];

    $types = '';
    $params = [];
    $whereParts = [];

    // Se nenhuma turma específica for selecionada, buscamos pelas categorias
    if (empty($turma)) {
        if (!empty($gre)) {
            $whereParts[] = buildWhereClause('gre', $gre, $types, $params);
        }
        if (!empty($escola)) {
            $whereParts[] = buildWhereClause('escola', $escola, $types, $params);
        }
        if (!empty($professor)) {
            $whereParts[] = buildWhereClause('professor', $professor, $types, $params);
        }
    } else {
        // Se turmas específicas forem selecionadas, priorizamos elas (ou combinamos com outros filtros)
        // Aqui assumimos que queremos turmas EXATAS dessas ID's, independentemente dos outros filtros
        // Para ser mais estrito: AND id IN (...)
        $whereParts[] = buildWhereClause('id', $turma, $types, $params);

        // Adiciona os outros filtros apenas se ainda existirem
        if (!empty($gre)) $whereParts[] = buildWhereClause('gre', $gre, $types, $params);
        if (!empty($escola)) $whereParts[] = buildWhereClause('escola', $escola, $types, $params);
        if (!empty($professor)) $whereParts[] = buildWhereClause('professor', $professor, $types, $params);
    }

    if (empty($whereParts)) {
        // Sem filtros válidos, busca tudo (opcional, dependendo da necessidade)
        $sql = "SELECT DISTINCT gre, escola, professor, turma, class_id FROM turmas ORDER BY turma";
    } else {
        $sql = "SELECT DISTINCT gre, escola, professor, turma, class_id FROM turmas WHERE " . implode(' AND ', $whereParts) . " ORDER BY turma";
    }

    try {
        $stmt = $conn->prepare($sql);
        if ($stmt === false) {
            throw new Exception("Preparação de consulta falhou: " . $conn->error);
        }
        if (!empty($params)) {
            $stmt->bind_param($types, ...$params);
        }
        $stmt->execute();
        return $stmt->get_result();
    } catch (Exception $e) {
        die("Erro na consulta: " . htmlspecialchars($e->getMessage(), ENT_QUOTES, 'UTF-8'));
    }
}

// --- Processamento de Filtros ---

if (isset($_GET['gre']) || isset($_GET['escola']) || isset($_GET['professor']) || isset($_GET['turma'])) {
    // Coletar filtros, garantindo que sejam arrays
