        'escola' => $_GET['escola'] ?? [],
        'professor' => $_GET['professor'] ?? [],
        'turma' => $_GET['turma'] ?? []
    ];

    $result = getFilteredTurmas($conn, $filters);

    if ($result && $result->num_rows > 0) {
        while ($row = $result->fetch_assoc()) {
            $turma_info[] = $row;
        }
    }
}

