            $('#turma').change(function() {
                $('#filtroForm').submit();
            });

            // Lidar com o envio do formulário configForm via AJAX com spinner de progresso
            $('#configForm').submit(function(e) {
                e.preventDefault();

                // Exibir o spinner de carregamento
                $('#loading').show();

                $.ajax({
                    url: $(this).attr('action'),
                    method: 'POST',
                    data: $(this).serialize(),
                    success: function(response) {
                        // Ocultar o spinner de carregamento
                        $('#loading').hide();
                        // Exibir o resultado
                        $('#configResult').html(response);
                    },
                    error: function() {
                        // Ocultar o spinner de carregamento
                        $('#loading').hide();
                        // Exibir mensagem de erro
                        $('#configResult').html('<div class="alert alert-danger">Erro ao carregar os links.</div>');
                    }
                });
            });
        });
    </script>
